using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using System.Windows.Media.Media3D;

using W=System.Windows;using WC=System.Windows.Controls;using WM=System.Windows.Media;using Shapes=System.Windows.Shapes;

namespace GearLab {

 public sealed partial class RobotDesignerForm {

  readonly Panel quickInspector=new Panel{Dock=DockStyle.Fill,AutoScroll=true};readonly TabControl inspectorTabs=new EditorTabs{Dock=DockStyle.Fill};readonly WC.Canvas boneOverlay=new WC.Canvas();readonly List<ToolStripButton> stages=new List<ToolStripButton>();SplitContainer sceneLayout;int stage;bool boneDragging,poseEditing;string poseBefore;Label quickLoad;W.Point boneStart;Vector3D boneDelta;

  void InitializeInspector(Control parentControl){var basic=new TabPage("Основное");var advanced=new TabPage("Все параметры");basic.Controls.Add(quickInspector);advanced.Controls.Add(properties);inspectorTabs.TabPages.AddRange(new[]{basic,advanced});parentControl.Controls.Add(inspectorTabs);}

  void InitializeRobotUX(ToolStrip top,ToolStrip tools,SplitContainer content){sceneLayout=content;tools.Visible=false;top.Items.Clear();var file=new ToolStripDropDownButton("Проект");file.DropDownItems.Add("Новый с нуля",null,(s,e)=>Replace(new RobotDocument(),null));file.DropDownItems.Add("РОБОТ1 · NEMA 17 · 800 мм",null,(s,e)=>Replace(RobotDocument.DefaultReference(),null));file.DropDownItems.Add("Кассетный корпус · другой вариант",null,(s,e)=>Replace(RobotDocument.CassetteReference(),null));file.DropDownItems.Add("Процедурный пример · NEMA 17 / 180 мм",null,(s,e)=>OpenProceduralExample());file.DropDownItems.Add("Открыть…",null,(s,e)=>Open());file.DropDownItems.Add("Сохранить",null,(s,e)=>Save(false));file.DropDownItems.Add("Сохранить как…",null,(s,e)=>Save(true));file.DropDownItems.Add("Восстановить автокопию",null,(s,e)=>RestoreRecovery());top.Items.Add(file);foreach(string title in new[]{"1 · Звенья","2 · Моторы","3 · Корпус","4 · Движение и нагрузки"}){int index=stages.Count;var b=new ToolStripButton(title){Padding=new Padding(6),CheckOnClick=false};b.Click+=(s,e)=>SetStage(index);stages.Add(b);top.Items.Add(b);}top.Items.Add(new ToolStripSeparator());Add(top,"Отмена",Undo);Add(top,"Повтор",Redo);var advanced=new ToolStripDropDownButton("Детали / экспорт");while(tools.Items.Count>0){var item=tools.Items[0];tools.Items.RemoveAt(0);advanced.DropDownItems.Add(item);}top.Items.Add(advanced);Add(top,"Справка",Help);Scene.Root.Children.Add(boneOverlay);Scene.ViewChanged+=RefreshBoneOverlay;Scene.Root.SizeChanged+=(s,e)=>RefreshBoneOverlay();Scene.Root.PreviewMouseWheel+=(s,e)=>Scene.Root.Dispatcher.BeginInvoke(new Action(RefreshBoneOverlay));Scene.Root.AddHandler(W.UIElement.MouseMoveEvent,new System.Windows.Input.MouseEventHandler((s,e)=>{if(e.LeftButton==System.Windows.Input.MouseButtonState.Pressed||e.MiddleButton==System.Windows.Input.MouseButtonState.Pressed)Scene.Root.Dispatcher.BeginInvoke(new Action(RefreshBoneOverlay));}),true);Scene.Root.AddHandler(W.UIElement.MouseUpEvent,new System.Windows.Input.MouseButtonEventHandler((s,e)=>Scene.Root.Dispatcher.BeginInvoke(new Action(RefreshBoneOverlay))),true);SetStage(0);}

  internal void SetStage(int value){EndPoseEdit();stage=value;for(int i=0;i<stages.Count;i++)stages[i].Checked=i==value;if(sceneLayout!=null)sceneLayout.Panel2Collapsed=value!=3;inspectorTabs.SelectedIndex=0;RefreshQuickInspector();RefreshBoneOverlay();UpdateWebPose();}

  static Label QuickLabel(string text,int height=26){return new Label{Text=text,Width=285,Height=height,Margin=new Padding(0,5,0,2)};}

  static void QuickButton(Control parent,string text,Action action){var b=new Button{Text=text,Width=285,Height=35,Margin=new Padding(0,4,0,2)};b.Click+=(s,e)=>action();parent.Controls.Add(b);}

  void RefreshQuickInspector(){if(quickInspector.Parent==null||poseEditing)return;quickLoad=null;jointControllers.Clear();quickInspector.SuspendLayout();foreach(Control old in quickInspector.Controls.Cast<Control>().ToArray())old.Dispose();quickInspector.Controls.Clear();var flow=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(8)};quickInspector.Controls.Add(flow);var j=Joint;if(j==null){flow.Controls.Add(QuickLabel("Добавьте первое звено. Начало будет закреплено на основании.",60));QuickButton(flow,"＋ Первое звено",AddJoint);QuickButton(flow,"Открыть готовый манипулятор",()=>Replace(RobotDocument.DefaultReference(),null));quickInspector.ResumeLayout();return;}flow.Controls.Add(QuickLabel(j.Name+" · "+Engine.F(j.Length)+" мм",35));var inputs=new Dictionary<string,TextBox>();Action<string,string,double> number=(key,label,value)=>{flow.Controls.Add(QuickLabel(label));var box=new TextBox{Text=Engine.N(value),Width=275};inputs[key]=box;flow.Controls.Add(box);};Func<string,double> read=key=>CADExpression.Evaluate(inputs[key].Text,null);

   if(stage==0){flow.Controls.Add(QuickLabel("Конец звена задаётся относительно шарнира. В сцене можно тянуть цветную ручку.",56));var name=new TextBox{Text=j.Name,Width=275};flow.Controls.Add(name);var mode=new EditorComboBox{Width=275,DropDownStyle=ComboBoxStyle.DropDownList};mode.Items.AddRange(Enum.GetNames(typeof(RobotJointMode)));mode.SelectedItem=j.Mode.ToString();flow.Controls.Add(mode);number("EndX","Конец X, мм",j.EndX);number("EndY","Конец Y, мм",j.EndY);number("EndZ","Конец Z, мм",j.EndZ);var offsetSwitch=new CheckBox{Text="Смещение начала звена X / Y / Z",Width=285};flow.Controls.Add(offsetSwitch);var offsets=new FlowLayoutPanel{AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Width=285,Visible=false};flow.Controls.Add(offsets);int offsetStart=flow.Controls.Count;number("OffsetX","Начало / смещение X, мм",j.OffsetX);number("OffsetY","Начало / смещение Y, мм",j.OffsetY);number("OffsetZ","Начало / смещение Z, мм",j.OffsetZ);foreach(Control c in flow.Controls.Cast<Control>().Skip(offsetStart).ToArray()){flow.Controls.Remove(c);offsets.Controls.Add(c);}offsetSwitch.CheckedChanged+=(s,e)=>offsets.Visible=offsetSwitch.Checked;QuickButton(flow,"Применить звено",()=>Mutate(()=>{j.Name=name.Text.Trim();j.Mode=(RobotJointMode)Enum.Parse(typeof(RobotJointMode),Convert.ToString(mode.SelectedItem));j.EndX=read("EndX");j.EndY=read("EndY");j.EndZ=read("EndZ");j.OffsetX=read("OffsetX");j.OffsetY=read("OffsetY");j.OffsetZ=read("OffsetZ");}));QuickButton(flow,"＋ Следующее звено",AddJoint);QuickButton(flow,"＋ Параллельная ветвь",()=>{var parentId=j.ParentId;Mutate(()=>{selectedJoint=Document.Add(parentId).Id;selectedPart=null;});});QuickButton(flow,"Удалить звено и потомков",Delete);}

   else if(stage==1){flow.Controls.Add(QuickLabel("Момент вводится на рабочих оборотах. NEMA задаёт габарит, а не мощность.",56));var motor=new EditorComboBox{Width=275,DropDownStyle=ComboBoxStyle.DropDownList};motor.Items.AddRange(Enum.GetNames(typeof(RobotMotorTemplate)));motor.SelectedItem=j.MotorTemplate.ToString();flow.Controls.Add(motor);number("MotorTorque","Момент мотора, Н·м",j.MotorTorque);number("MotorMaxRpm","Рабочие обороты мотора, об/мин",j.MotorMaxRpm);number("Reduction","Передача |i|",j.Reduction);number("Efficiency","КПД (0–1)",j.Efficiency);number("MotorMass","Масса мотора, кг",j.MotorMass);number("Payload","Нагрузка на конце звена, кг",j.Payload);QuickButton(flow,"Применить привод и нагрузку",()=>Mutate(()=>{var template=(RobotMotorTemplate)Enum.Parse(typeof(RobotMotorTemplate),Convert.ToString(motor.SelectedItem));if(template!=j.MotorTemplate){j.MotorTemplate=template;j.ApplyMotorTemplate();}j.MotorTorque=read("MotorTorque");j.MotorMaxRpm=read("MotorMaxRpm");j.Reduction=read("Reduction");j.Efficiency=read("Efficiency");j.MotorMass=read("MotorMass");j.Payload=read("Payload");}));QuickButton(flow,"Спроектировать редуктор…",Reducer);QuickButton(flow,"Собрать свою передачу…",Transmission);}

   else if(stage==2){QuickButton(flow,"Форма РОБОТ1 → всем",ApplyBlenderDesign);QuickButton(flow,"Кассетный корпус → всем",ApplyReferenceDesign);QuickButton(flow,"Обновить стыки · 5.4",ReconnectRobot);QuickButton(flow,"Процедурный корпус · 5 вариантов",OpenProceduralBody);QuickButton(flow,Document.ReferenceGripper?"Убрать захват":"Добавить двухпальцевый захват",ToggleReferenceGripper);if(j.BodyGenerator!=null&&j.BodyGenerator.Enabled){if(j.BodyGenerator.BlenderDesign){flow.Controls.Add(QuickLabel("РОБОТ1 · Г-образные звенья, точные цилиндры и круглые повороты.",58));number("SkinDiameter","Диаметр трубчатого звена, мм",j.SkinDiameter);QuickButton(flow,"Применить диаметр",()=>Mutate(()=>j.SkinDiameter=read("SkinDiameter")));}flow.Controls.Add(QuickLabel("Процедурный режим включён. Изменение механики перестраивает связанные детали.",62));QuickButton(flow,"Вернуться к простому корпусу",()=>Mutate(()=>j.BodyGenerator.Enabled=false));flow.Controls.Add(QuickLabel("Стенки, посадки, крепления, профиль и цветные панели настраиваются в процедурном редакторе. Для внешней правки экспортируйте STEP.",110));quickInspector.ResumeLayout();return;}flow.Controls.Add(QuickLabel("Изменения корпуса применяются к выбранному звену. Размеры задаются ниже; внешняя правка — через STEP.",64));var style=new EditorComboBox{Width=275,DropDownStyle=ComboBoxStyle.DropDownList};style.Items.AddRange(Enum.GetNames(typeof(RobotBodyStyle)));style.SelectedItem=j.BodyStyle.ToString();flow.Controls.Add(style);number("SkinDiameter","Диаметр трубчатого звена, мм",j.SkinDiameter);number("Wall","Стенка корпуса, мм",j.Wall);number("BeamWidth","Ширина балки, мм",j.BeamWidth);number("BeamThickness","Толщина балки, мм",j.BeamThickness);number("BoltDiameter","Крепёж Ø, мм",j.BoltDiameter);number("Fit","Посадочный зазор, мм",j.Fit);var cables=new CheckBox{Text="Каналы / габариты проводки",Checked=j.Cables,Width=280};flow.Controls.Add(cables);QuickButton(flow,"Перестроить корпус звена",()=>Mutate(()=>{j.BodyStyle=(RobotBodyStyle)Enum.Parse(typeof(RobotBodyStyle),Convert.ToString(style.SelectedItem));j.SkinDiameter=read("SkinDiameter");j.Wall=read("Wall");j.BeamWidth=read("BeamWidth");j.BeamThickness=read("BeamThickness");j.BoltDiameter=read("BoltDiameter");j.Fit=read("Fit");j.Cables=cables.Checked;}));QuickButton(flow,"Трубчатый корпус всем звеньям",ApplyEnclosedStyle);QuickButton(flow,"Показать варианты корпусов",Variants);}

   else{BuildJointControllers(flow);}

   quickInspector.ResumeLayout();}

  void RefreshQuickLoad(){if(quickLoad==null||Analysis==null)return;var state=Analysis.Joints.FirstOrDefault(x=>x.Id==selectedJoint);if(state!=null)quickLoad.Text="Нужно с запасом: "+Engine.F(state.Required)+" "+state.Unit+"\nДоступно: "+Engine.F(state.Available)+" "+state.Unit+"\n"+state.Message;}

  void BeginPoseEdit(){if(poseEditing)return;Stop();poseEditing=true;poseBefore=Document.Serialize();if(Math.Abs(phase)>1e-9){var current=RobotKinematics.Evaluate(Document,phase,true);foreach(var j in Document.Joints)j.Position=current[j.Id].Value;phase=0;}}

  internal void SetJointPose(string id,double value){var joint=Document.Find(id);if(joint==null||!MechanismCad.Finite(value))return;Stop();joint.Position=Math.Max(joint.Minimum,Math.Min(joint.Maximum,value));RefreshManualPose();}

  void EndPoseEdit(){if(!poseEditing)return;string current=Document.Serialize();if(poseBefore!=current){undo.Push(poseBefore);redo.Clear();}last=current;poseEditing=false;poseBefore=null;Text="GearLab 6.4 · "+Document.Name+(last!=saved?" *":"");SyncJointControllers();}

  W.Point ProjectBone(Point3D point){var d=point-Scene.Camera.Target;double scale=Scene.Root.ActualWidth/Math.Max(.01,Scene.Camera.Width);return new W.Point(Scene.Root.ActualWidth/2+Vector3D.DotProduct(d,Scene.Camera.Right)*scale,Scene.Root.ActualHeight/2-Vector3D.DotProduct(d,Scene.Camera.Up)*scale);}

  void RefreshBoneOverlay(){if(boneDragging||boneOverlay.Parent==null||Build==null||!Scene.Ready)return;boneOverlay.Children.Clear();if(stage!=0&&view.SelectedIndex!=0&&(move==null||!move.Checked))return;var poses=RobotKinematics.Evaluate(Document,phase,Math.Abs(phase)>1e-9);foreach(var j in Document.Joints){var p=poses[j.Id];var origin=ProjectBone(p.Origin);var dot=new WC.Button{Content=(Document.Joints.IndexOf(j)+1).ToString(),Width=27,Height=27,Background=j.Id==selectedJoint?WM.Brushes.DarkOrange:WM.Brushes.SteelBlue,Foreground=WM.Brushes.White,ToolTip=j.Name+" · выбрать шарнир"};WC.Canvas.SetLeft(dot,origin.X-13);WC.Canvas.SetTop(dot,origin.Y-13);string id=j.Id;dot.Click+=(s,e)=>Select(id,null);boneOverlay.Children.Add(dot);if(j.Id!=selectedJoint)continue;var tip=ProjectBone(p.Tip);var line=new Shapes.Line{X1=origin.X,Y1=origin.Y,X2=tip.X,Y2=tip.Y,Stroke=WM.Brushes.DarkOrange,StrokeThickness=2,StrokeDashArray=new WM.DoubleCollection(new[]{4.0,3}),IsHitTestVisible=false};boneOverlay.Children.Add(line);var label=new WC.TextBlock{Text=j.Name+" · "+Engine.F(j.Length)+" мм",Background=WM.Brushes.White,Foreground=WM.Brushes.DarkSlateGray,Padding=new W.Thickness(5),IsHitTestVisible=false};WC.Canvas.SetLeft(label,tip.X+16);WC.Canvas.SetTop(label,tip.Y-10);boneOverlay.Children.Add(label);if(playing||Math.Abs(phase)>1e-9)continue;var thumb=new System.Windows.Controls.Primitives.Thumb{Width=23,Height=23,Background=WM.Brushes.OrangeRed,ToolTip="Потяните конец звена. Ось перемещения задаётся над сценой."};var border=new W.FrameworkElementFactory(typeof(WC.Border));border.SetValue(WC.Border.BackgroundProperty,WM.Brushes.OrangeRed);border.SetValue(WC.Border.CornerRadiusProperty,new W.CornerRadius(12));thumb.Template=new WC.ControlTemplate(typeof(System.Windows.Controls.Primitives.Thumb)){VisualTree=border};WC.Canvas.SetLeft(thumb,tip.X-11);WC.Canvas.SetTop(thumb,tip.Y-11);thumb.DragStarted+=(s,e)=>{boneDragging=true;boneStart=System.Windows.Input.Mouse.GetPosition(Scene.Root);boneDelta=new Vector3D();};thumb.DragDelta+=(s,e)=>{boneDelta=Scene.DragDelta(boneStart,System.Windows.Input.Mouse.GetPosition(Scene.Root));WC.Canvas.SetLeft(thumb,ProjectBone(p.Tip+boneDelta).X-11);WC.Canvas.SetTop(thumb,ProjectBone(p.Tip+boneDelta).Y-11);};thumb.DragCompleted+=(s,e)=>{boneDragging=false;if(!e.Canceled&&boneDelta.LengthSquared>1e-8)CommitDrag(id+"_end_guide",boneDelta);RefreshBoneOverlay();};boneOverlay.Children.Add(thumb);}}

 }

